package hotel.room;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/**
 * A room as it is stored in the database (table "room").
 * hotel.model.Room stays unchanged: it is immutable, JPA needs its own class.
 */
@Entity
@Table(name = "room")
public class RoomEntity {

    /** Set by the admin, not generated by the database. */
    @Id
    private Integer roomNumber;

    @Column(nullable = false)
    private int capacity;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal pricePerNight;

    /** Needed by JPA. */
    protected RoomEntity() {
    }

    public RoomEntity(int roomNumber, int capacity, BigDecimal pricePerNight) {
        this.roomNumber = roomNumber;
        this.capacity = capacity;
        this.pricePerNight = pricePerNight;
    }

    public Integer getRoomNumber() {
        return roomNumber;
    }

    public int getCapacity() {
        return capacity;
    }

    public void setCapacity(int capacity) {
        this.capacity = capacity;
    }

    public BigDecimal getPricePerNight() {
        return pricePerNight;
    }

    public void setPricePerNight(BigDecimal pricePerNight) {
        this.pricePerNight = pricePerNight;
    }
}
